import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import MegaNav from "@/components/MegaNav/MegaNav";
import { pageOpenGraph } from "@/config/navigation";
import {
  DEFAULT_THEME_LABEL,
  THEME_PRESETS,
  THEME_SELECTOR_ORDER,
} from "@/lib/theme/presets";
import { ThemeSpecimen } from "./ThemeSpecimen";

/**
 * One theme as a specimen: every visual element of the system drawn in
 * that theme, beside the theme's own DESIGN.md. The file is generated by
 * scripts/generate-theme-design-md.mjs into public/themes/<id>/, and this
 * page reads the same file at build time, so the DESIGN.md tab and the
 * download are one artifact.
 */

export const dynamicParams = false;

export function generateStaticParams() {
  return THEME_SELECTOR_ORDER.map((id) => ({ id }));
}

const labelOf = (id: string) => THEME_PRESETS[id]?.label ?? DEFAULT_THEME_LABEL;

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>;
}): Promise<Metadata> {
  const { id } = await params;
  const title = `${labelOf(id)} theme`;
  const description = `The ${labelOf(id)} theme as a specimen: colour, type, shape, surfaces and controls, with its DESIGN.md to download.`;
  const href = `/foundations/themes/${id}`;
  return {
    title,
    description,
    alternates: { canonical: href },
    openGraph: pageOpenGraph(title, description, href),
  };
}

export default async function ThemeSpecimenPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  if (!THEME_SELECTOR_ORDER.includes(id)) notFound();
  const designMd = readFileSync(
    join(process.cwd(), "public", "themes", id, "DESIGN.md"),
    "utf8"
  );

  return (
    <>
      <MegaNav />
      <ThemeSpecimen
        id={id}
        label={labelOf(id)}
        designMd={designMd}
      />
    </>
  );
}
